resource "google_app_engine_standard_app_version" "<example_resource_name>" {
  version_id = "v2"
  service    = "default"
  runtime    = "php84" # Critical: supported PHP runtime to pass the check

  entrypoint {
    shell = "serve index.php"
  }

  deployment {
    zip {
      source_url = "https://storage.googleapis.com/<example_resource_id>/app.zip"
    }
  }
}
